// Shared money formatting. Amounts are integer cents.
const CURRENCIES = {
  USD: { symbol: '$', position: 'prefix', group: ',', decimal: '.' },
  GBP: { symbol: '£', position: 'prefix', group: ',', decimal: '.' },
  EUR: { symbol: '€', position: 'suffix', group: '.', decimal: ',' },
};

const NEGATIVE_STYLES = ['minus', 'parens'];

function groupDigits(intStr, sep) {
  return intStr.replace(/\B(?=(\d{3})+(?!\d))/g, sep);
}

/**
 * formatMoney(123456)                              -> "$1,234.56"
 * formatMoney(-500, 'EUR')                         -> "-5,00 €"
 * formatMoney(-123456, { negativeStyle: 'parens' }) -> "($1,234.56)"
 * formatMoney(-500, { currency: 'EUR', negativeStyle: 'parens' }) -> "(5,00 €)"
 *
 * Second argument is either a currency code (positional form) or an options
 * object: { currency = 'USD', negativeStyle = 'minus' | 'parens' }.
 */
export function formatMoney(cents, options = 'USD') {
  const opts = typeof options === 'string' ? { currency: options } : (options ?? {});
  const { currency = 'USD', negativeStyle = 'minus' } = opts;

  const spec = Object.hasOwn(CURRENCIES, currency) ? CURRENCIES[currency] : undefined;
  if (!spec) throw new RangeError(`unknown currency: ${currency}`);
  if (!NEGATIVE_STYLES.includes(negativeStyle)) {
    throw new RangeError(`unknown negativeStyle: ${negativeStyle}`);
  }
  if (!Number.isInteger(cents)) throw new TypeError('cents must be an integer');

  const negative = cents < 0;
  const abs = Math.abs(cents);
  const whole = groupDigits(String(Math.floor(abs / 100)), spec.group);
  const frac = String(abs % 100).padStart(2, '0');
  const number = `${whole}${spec.decimal}${frac}`;
  const body = spec.position === 'prefix' ? `${spec.symbol}${number}` : `${number} ${spec.symbol}`;

  if (!negative) return body;
  return negativeStyle === 'parens' ? `(${body})` : `-${body}`;
}

