// Token bucket. `capacity` is the maximum burst size; tokens refill continuously at
// `refillPerSec` tokens per second, measured with the injected clock `now()` (ms).
export class TokenBucket {
  constructor({ capacity, refillPerSec, now = () => Date.now() }) {
    if (!(capacity > 0)) throw new RangeError('capacity must be > 0');
    if (!(refillPerSec >= 0)) throw new RangeError('refillPerSec must be >= 0');
    this.capacity = capacity;
    this.refillPerSec = refillPerSec;
    this.now = now;
    this._tokens = capacity;
    this.last = now();
  }

  _refill() {
    const t = this.now();
    const elapsed = t - this.last;
    // Clock did not advance or went backwards: add nothing and keep `last`,
    // so time already elapsed is not counted twice when the clock recovers.
    if (!(elapsed > 0)) return;
    const added = (elapsed / 1000) * this.refillPerSec;
    this._tokens = Math.min(this.capacity, this._tokens + added);
    this.last = t;
  }

  /** Current (possibly fractional) token count. */
  get tokens() {
    this._refill();
    return this._tokens;
  }

  /** Try to take n tokens. Returns true if allowed; a rejected request consumes nothing. */
  tryRemove(n = 1) {
    if (!(n >= 0)) throw new RangeError('n must be >= 0');
    this._refill();
    if (this._tokens < n) return false;
    this._tokens -= n;
    return true;
  }
}

