// Token bucket. `capacity` is the maximum burst size; tokens refill continuously at
// `refillPerSec` tokens per second, measured with the injected clock `now()` (ms).

// Tolerance for floating-point drift when comparing fractional token counts.
const EPS = 1e-9;

export class TokenBucket {
  constructor({ capacity, refillPerSec, now = () => Date.now() }) {
    if (!(capacity > 0)) throw new RangeError('capacity must be > 0');
    if (!(refillPerSec >= 0)) throw new RangeError('refillPerSec must be >= 0');
    this.capacity = capacity;
    this.refillPerSec = refillPerSec;
    this.now = now;
    this._tokens = capacity;
    this.last = now();
  }

  _refill() {
    const t = this.now();
    const elapsed = t - this.last;
    // Clock stalled or went backwards: credit nothing. Keep `last` at the
    // high-water mark so the same interval is never credited twice.
    if (!(elapsed > 0)) return;
    this._tokens = Math.min(
      this.capacity,
      this._tokens + (elapsed / 1000) * this.refillPerSec,
    );
    this.last = t;
  }

  /** Current (possibly fractional) token count, always within [0, capacity]. */
  get tokens() {
    this._refill();
    return this._tokens;
  }

  /** Try to take n tokens. Returns true if allowed; a rejected call consumes nothing. */
  tryRemove(n = 1) {
    if (!(n >= 0)) throw new RangeError('n must be >= 0');
    this._refill();
    if (this._tokens + EPS < n) return false;
    this._tokens = Math.max(0, this._tokens - n);
    return true;
  }
}
